78	/**
79	 * Returns the share URL for a MemoShare resource.
80	 * The token is the last path segment of the share name (memos/{uid}/shares/{token}).
81	 */
82	export function getShareUrl(share: MemoShare): string {
83	  const token = share.name.split("/").pop() ?? "";
84	  return `${window.location.origin}/memos/shares/${token}`;
85	}
